    """Reduce a grid of 3x3 cells to one cell per block, preserving marker colors."""
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    out = [[0 for _ in range((cols + 2) // 3)] for _ in range((rows + 2) // 3)]
    for r in range(rows):
        for c in range(cols):
            value = grid[r][c]
            if value not in (0, 5):
                out[r // 3][c // 3] = value
    return out
